      "preview": "很多产品做大模型落地，第一反应都是在顶部堆一个庞大的「AI 总结卡片」，大众点评反过来，在真实用户的长评，用荧光笔划线的样式把关键建议标出来。大家看大众点评，图的就是普通人字里行间的真实细节，如果全压成干巴巴的机器摘要，信任感立刻折损大半。"
