      "text": "Cindy 开源第三周。本周继续更新了很多有趣的功能，但是也出现了一些阻断性的 Bug。下周开始我们可能会稍微降低正式版的更新频率，保证大家的稳定性。另外再单独出个测试版来日更。另外还想再花点精力在新手和付费体验上，让大家能意识到，Cindy 是个正儿八经的的，能买到超值好服务的产品。",
